@SpringBootTest(properties={"bridgeops.auth.enabled=true","bridgeops.auth.origin=https://bridgeops.invalid","bridgeops.auth.issuer=recovery-test","bridgeops.auth.key-id=recovery-test"})
@AutoConfigureMockMvc @Testcontainers @Import(PasswordRecoveryIT.Configuration.class)
class PasswordRecoveryIT {
 static final TestAuthMaterial keys=new TestAuthMaterial();static final Instant NOW=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);static final String ORIGIN="https://bridgeops.invalid";
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:77f585114c32fbca283dc835b0596f4e52b51b4c6662d7810b2f4084f60a1873").asCompatibleSubstituteFor("postgres")).withInitScript("organization-runtime.sql");
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",()->"bridgeops_app");r.add("spring.datasource.password",()->"synthetic-runtime-fixture");r.add("spring.flyway.user",postgres::getUsername);r.add("spring.flyway.password",postgres::getPassword);r.add("bridgeops.auth.private-key",()->keys.directory.resolve("private.pem").toString());r.add("bridgeops.auth.public-key",()->keys.directory.resolve("public.pem").toString());r.add("bridgeops.auth.csrf-key",()->keys.directory.resolve("csrf.key").toString());}
 @Autowired MockMvc mvc;@Autowired PasswordRecoveryService recovery;@Autowired PasswordSessionService sessions;@Autowired AccessTokens access;@Autowired AccountPasswords passwords;@Autowired MailSink sink;@Autowired TestClock clock;@Autowired javax.sql.DataSource runtime;
 JdbcTemplate jdbc;UUID user;static String oldHash;static final String OLD="synthetic-old-password",NEW="synthetic-new-password";
 record Browser(Cookie csrf,Cookie refresh,String access){@Override public String toString(){return "Browser[REDACTED]";}}
 @BeforeEach void fixture(){jdbc=new JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()));jdbc.execute("TRUNCATE users,installation_state,authentication_throttles CASCADE");clock.now=NOW;sink.messages.clear();sink.fail=false;sink.attempts.set(0);if(oldHash==null)oldHash=passwords.hash(OLD);user=UUID.randomUUID();jdbc.update("INSERT INTO users(id,email,normalized_email,password_hash,display_name,account_status,created_at,email_verified_at) VALUES(?,?,?,?,'Fixture','ACTIVE',?,?)",user,"recover@example.invalid","recover@example.invalid",oldHash,java.sql.Timestamp.from(NOW),java.sql.Timestamp.from(NOW));}
 Browser anonymous()throws Exception{var response=mvc.perform(get("/api/v1/auth/csrf")).andExpect(status().isOk()).andReturn().getResponse();return new Browser(response.getCookie("__Host-bridgeops-csrf"),null,null);}
 Browser signedIn()throws Exception{var grant=(com.bridgeops.identity.domain.SessionOutcome.Granted)sessions.authenticate("recover@example.invalid",OLD);var refresh=new Cookie("__Host-bridgeops-refresh",grant.refreshToken());var response=mvc.perform(get("/api/v1/auth/csrf").cookie(refresh)).andReturn().getResponse();return new Browser(response.getCookie("__Host-bridgeops-csrf"),refresh,access.issue(grant).value());}
 ResultActions postBody(String path,Browser browser,Object body)throws Exception{var request=post("/api/v1/auth/"+path).header("Origin",ORIGIN).cookie(browser.csrf()).header("X-CSRF-TOKEN",browser.csrf().getValue()).contentType("application/json").content(new ObjectMapper().writeValueAsString(body));if(browser.refresh()!=null)request.cookie(browser.refresh());if(browser.access()!=null)request.header("Authorization","Bearer "+browser.access());return mvc.perform(request);}
 ResultActions reset(String token,String password)throws Exception{return postBody("reset",anonymous(),Map.of("token",token,"newPassword",password));}
 String proof(){recovery.forgot("recover@example.invalid");return sink.token();}
 @Test void changeRevokesEveryFamilyAndPendingProofAndClearsCookies()throws Exception{var one=signedIn();var two=signedIn();String token=proof();var response=postBody("password/change",one,Map.of("currentPassword",OLD,"newPassword",NEW)).andExpect(status().isNoContent()).andReturn().getResponse();assertThat(response.getHeader("Cache-Control")).contains("no-store");assertThat(response.getCookie("__Host-bridgeops-refresh").getMaxAge()).isZero();for(var b:List.of(one,two))mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+b.access())).andExpect(status().isUnauthorized());assertThat(passwords.matches(NEW,jdbc.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,user))).isTrue();reset(token,NEW).andExpect(status().isBadRequest());}
 @Test void incorrectCurrentPasswordAndWeakReplacementCannotChangeCredentials()throws Exception{var b=signedIn();for(var body:List.of(Map.of("currentPassword","incorrect","newPassword",NEW),Map.of("currentPassword",OLD,"newPassword","short")))postBody("password/change",b,body).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+b.access())).andExpect(status().isOk());assertThat(jdbc.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,user)).isEqualTo(oldHash);}
 @Test void resetConsumesHashOnlyProofAndRevokesExistingAccess()throws Exception{var b=signedIn();String token=proof();assertThat(jdbc.queryForObject("SELECT token_hash FROM password_reset_tokens",String.class)).hasSize(64).isNotEqualTo(token);reset(token,NEW).andExpect(status().isNoContent());reset(token,NEW).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+b.access())).andExpect(status().isUnauthorized());assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_security_events WHERE event_type='PASSWORD_RESET'",Integer.class)).isEqualTo(1);}
 @Test void invalidExpiredAndWeakResetCannotConsumeProof()throws Exception{String token=proof();reset("a".repeat(43),NEW).andExpect(status().isBadRequest());reset(token,"short").andExpect(status().isBadRequest());assertThat(jdbc.queryForObject("SELECT consumed_at IS NULL FROM password_reset_tokens",Boolean.class)).isTrue();clock.now=NOW.plusSeconds(900);reset(token,NEW).andExpect(status().isBadRequest());assertThat(jdbc.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,user)).isEqualTo(oldHash);}
 @Test void concurrentResetHasExactlyOneWinner()throws Exception{String token=proof();var a=anonymous();var b=anonymous();var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<Integer> first=()->{gate.await();return postBody("reset",a,Map.of("token",token,"newPassword",NEW)).andReturn().getResponse().getStatus();};Callable<Integer> second=()->{gate.await();return postBody("reset",b,Map.of("token",token,"newPassword",NEW)).andReturn().getResponse().getStatus();};var x=pool.submit(first);var y=pool.submit(second);gate.countDown();assertThat(List.of(x.get(25,TimeUnit.SECONDS),y.get(25,TimeUnit.SECONDS))).containsExactlyInAnyOrder(204,400);}}
 @Test void forgotAcknowledgementIsGenericAndOnlyVerifiedActiveRecipientsReceiveMail()throws Exception{var a=anonymous();String known=postBody("forgot",a,Map.of("email","recover@example.invalid")).andExpect(status().isAccepted()).andReturn().getResponse().getContentAsString();String unknown=postBody("forgot",a,Map.of("email","missing@example.invalid")).andExpect(status().isAccepted()).andReturn().getResponse().getContentAsString();assertThat(known).isEqualTo(unknown).doesNotContain("email was sent");org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(8)).until(()->sink.messages.size()==1);jdbc.update("UPDATE users SET email_verified_at=NULL WHERE id=?",user);recovery.forgot("recover@example.invalid");jdbc.update("UPDATE users SET email_verified_at=?,account_status='DISABLED' WHERE id=?",java.sql.Timestamp.from(NOW),user);recovery.forgot("recover@example.invalid");assertThat(sink.messages).hasSize(1);}
 @Test void failedDeliveryRollsBackAndPublicResponseDoesNotClaimDelivery()throws Exception{String old=proof();sink.fail=true;assertThatThrownBy(()->recovery.forgot("recover@example.invalid")).isInstanceOf(DomainFailure.class).hasNoCause();assertThat(jdbc.queryForObject("SELECT consumed_at IS NULL FROM password_reset_tokens",Boolean.class)).isTrue();postBody("forgot",anonymous(),Map.of("email","recover@example.invalid")).andExpect(status().isAccepted()).andExpect(jsonPath("$.message").value(org.hamcrest.Matchers.containsString("Delivery is not guaranteed")));org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(8)).until(()->sink.attempts.get()>=3);reset(old,NEW).andExpect(status().isNoContent());}
 @Test void missingOriginCsrfIdentityAndUnknownFieldsAreRejected()throws Exception{mvc.perform(post("/api/v1/auth/forgot").contentType("application/json").content("{\"email\":\"recover@example.invalid\"}")).andExpect(status().isForbidden());postBody("password/change",anonymous(),Map.of("currentPassword",OLD,"newPassword",NEW)).andExpect(status().isUnauthorized());postBody("forgot",anonymous(),Map.of("email","recover@example.invalid","userId",user.toString())).andExpect(status().isBadRequest());var a=anonymous();mvc.perform(post("/api/v1/auth/reset").header("Origin","https://foreign.invalid").cookie(a.csrf()).header("X-CSRF-TOKEN",a.csrf().getValue()).contentType("application/json").content("{}")).andExpect(status().isForbidden());}
 @Test void quotasBoundForgotAndInvalidResetAttempts()throws Exception{var a=anonymous();for(int i=0;i<10;i++)postBody("forgot",a,Map.of("email","missing@example.invalid")).andExpect(status().isAccepted());postBody("forgot",a,Map.of("email","missing@example.invalid")).andExpect(status().isTooManyRequests());for(int i=0;i<10;i++)postBody("reset",a,Map.of("token","b".repeat(43),"newPassword","short")).andExpect(status().isBadRequest());postBody("reset",a,Map.of("token","b".repeat(43),"newPassword","short")).andExpect(status().isTooManyRequests());}
 @Test void auditFailureRollsBackPasswordProofConsumptionAndRevocation()throws Exception{var b=signedIn();String token=proof();jdbc.execute("CREATE FUNCTION reject_reset_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type='PASSWORD_RESET' THEN RAISE EXCEPTION 'synthetic rollback'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER reject_reset_audit BEFORE INSERT ON identity_security_events FOR EACH ROW EXECUTE FUNCTION reject_reset_audit()");try{reset(token,NEW).andExpect(status().isServiceUnavailable());}finally{jdbc.execute("DROP TRIGGER reject_reset_audit ON identity_security_events");jdbc.execute("DROP FUNCTION reject_reset_audit()");}assertThat(jdbc.queryForObject("SELECT consumed_at IS NULL FROM password_reset_tokens",Boolean.class)).isTrue();assertThat(jdbc.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,user)).isEqualTo(oldHash);mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+b.access())).andExpect(status().isOk());}
 @Test void runtimeCanConsumeButCannotExtendProofsOrInsertGenericUsers(){var app=new JdbcTemplate(runtime);assertThat(app.queryForObject("SELECT has_column_privilege(current_user,'password_reset_tokens','consumed_at','UPDATE')",Boolean.class)).isTrue();assertThat(app.queryForObject("SELECT has_column_privilege(current_user,'password_reset_tokens','expires_at','UPDATE')",Boolean.class)).isFalse();assertThat(app.queryForObject("SELECT has_table_privilege(current_user,'users','INSERT')",Boolean.class)).isFalse();}
 @Test void aNewRequestInvalidatesOlderProofs()throws Exception{String first=proof();String second=proof();reset(first,NEW).andExpect(status().isBadRequest());reset(second,NEW).andExpect(status().isNoContent());}
 @Test void disabledOrNoLongerVerifiedAccountsCannotUseIssuedProof()throws Exception{String token=proof();jdbc.update("UPDATE users SET account_status='DISABLED' WHERE id=?",user);reset(token,NEW).andExpect(status().isBadRequest());jdbc.update("UPDATE users SET account_status='ACTIVE',email_verified_at=NULL WHERE id=?",user);reset(token,NEW).andExpect(status().isBadRequest());}
 @Test void deliveredButRolledBackRecoveryProofIsUnusable()throws Exception{jdbc.execute("CREATE FUNCTION reject_recovery_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type='PASSWORD_RECOVERY_REQUESTED' THEN RAISE EXCEPTION 'synthetic rollback'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER reject_recovery_audit BEFORE INSERT ON identity_security_events FOR EACH ROW EXECUTE FUNCTION reject_recovery_audit()");try{assertThatThrownBy(()->recovery.forgot("recover@example.invalid")).isInstanceOf(RuntimeException.class);}finally{jdbc.execute("DROP TRIGGER reject_recovery_audit ON identity_security_events");jdbc.execute("DROP FUNCTION reject_recovery_audit()");}assertThat(sink.messages).hasSize(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM password_reset_tokens",Integer.class)).isZero();reset(sink.token(),NEW).andExpect(status().isBadRequest());}
 @AfterAll static void cleanup()throws Exception{keys.close();}
 static class TestClock extends Clock{volatile Instant now=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return now;}}
 static class MailSink implements OutboundEmail {final List<String> messages=new CopyOnWriteArrayList<>();final java.util.concurrent.atomic.AtomicInteger attempts=new java.util.concurrent.atomic.AtomicInteger();volatile boolean fail;public void send(String recipient,String subject,String text){attempts.incrementAndGet();if(fail)throw new DomainFailure(503,"DELIVERY_UNAVAILABLE");messages.add(text);}String token(){return messages.getLast().lines().filter(line->line.matches("[A-Za-z0-9_-]{43}")).findFirst().orElseThrow();}}
 @TestConfiguration static class Configuration{@Bean @Primary TestClock recoveryClock(){return new TestClock();}@Bean @Primary MailSink recoveryMailSink(){return new MailSink();}}
}
